async function init(){await clearLocalBooksOnce();books=await getBooks()||cloneBooks();bindRoom();document.querySelectorAll('.character-choice').forEach(button=>button.onclick=()=>{selectedCharacter=button.dataset.character;document.querySelectorAll('.character-choice').forEach(x=>x.setAttribute('aria-pressed',String(x===button)));$('#character-status').textContent=`Today, you’re here as ${selectedCharacter}.`});if(location.search.includes('collection=1'))await openShare();renderShelf();document.querySelector('#about-button').onclick=about;document.querySelector('#writer-entry').onclick=writerGate;document.querySelector('#lock-room').onclick=lockRoom;document.querySelector('#atmosphere-toggle').onclick=toggleAtmosphere;document.querySelector('#sound-toggle').onclick=toggleSound;document.querySelector('#view-toggle').onclick=()=>$('#view-popover').hidden=!$('#view-popover').hidden;document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>showView(b.dataset.view));document.querySelector('#close-book').onclick=closeBook;document.querySelector('#prev-page').onclick=()=>turn(-1);document.querySelector('#next-page').onclick=()=>turn(1);reader.onclick=e=>{if(e.target===reader)closeBook()};document.addEventListener('keydown',keys);setupSwipe();timeLighting();if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{});}
function bindRoom(){window.addEventListener('pointerdown',()=>{lastTouch=Date.now()},{passive:true});window.addEventListener('keydown',()=>{lastTouch=Date.now()});setInterval(()=>{if(writer&&Date.now()-lastTouch>600000)lockRoom()},15000)}
function timeLighting(){const h=new Date().getHours(),roomEl=room;let warm=1,dim=1;if(h>=21||h<6){warm=1.18;dim=.74}else if((h>=5&&h<9)||(h>=17&&h<21))warm=1.14;roomEl.style.setProperty('--time-warm',warm);roomEl.style.filter=`brightness(${dim}) sepia(${Math.max(0,warm-1)*.12})`}
function unreadCount(book){const read=JSON.parse(localStorage.getItem('memory-bookshelf-read')||'{}');return book.spreads.filter(s=>!(read[book.id]||[]).includes(s.id)).length}
function renderShelf(){const shelf=$('#book-shelf');shelf.innerHTML='';const active=books.filter(b=>!b.archived);$('#book-count').textContent=`${active.length} ${active.length===1?'book':'books'}`;active.forEach((b,i)=>{const el=document.createElement('button');el.className='spine'+(unreadCount(b)?' unread':'');el.style.setProperty('--book',b.color||['#60766a','#994d3b','#b18a58','#4e6571'][i%4]);el.style.setProperty('--h',`${112+(i*17%62)}px`);el.draggable=writer;el.dataset.id=b.id;el.setAttribute('aria-label',`${b.title}${unreadCount(b)?`, ${unreadCount(b)} unread spreads`:''}`);el.innerHTML=`<span class="spine-title">${esc(b.title)}</span><span class="spine-dots">${b.lock?'▣':'✳'}</span>`;el.onclick=()=>openBook(b);el.addEventListener('dragstart',e=>{dragging={type:'book',id:b.id};e.dataTransfer.setData('text/plain',b.id)});el.addEventListener('dragover',e=>e.preventDefault());el.addEventListener('drop',e=>{e.preventDefault();if(!writer||!dragging||dragging.type!=='book')return;const from=books.findIndex(x=>x.id===dragging.id),to=books.findIndex(x=>x.id===b.id);const [moving]=books.splice(from,1);books.splice(to,0,moving);pushHistory();scheduleSave();renderShelf()});shelf.append(el)});if(writer){const add=document.createElement('button');add.className='spine add-spine';add.style.setProperty('--book','#8a7158');add.innerHTML='<span class="spine-title">New journal</span><span class="spine-dots">＋</span>';add.onclick=addBook;shelf.append(add)}}
function openBook(book){if(book.lock&&!writer){showDialog(`<h2>This journal is closed</h2><p>${esc(book.lock.prompt||'Enter the date to open this book.')}</p><label>Key</label><input id="book-lock" type="password" autocomplete="off"><div class="dialog-actions"><button id="unlock-book">Open</button></div>`);$('#unlock-book').onclick=()=>{if($('#book-lock').value===book.lock.value){book.lock=null;dialog.close();enterBook(book)}else alert('That key did not open this one.');};return}enterBook(book)}
function enterBook(book){currentBook=book;currentIndex=-1;room.hidden=true;reader.hidden=false;reader.style.animationDuration=reduced?'0ms':'550ms';$('#reader-book-title').textContent=selectedCharacter?`${book.title} · ${selectedCharacter}`:book.title;renderSpread();if(!installHintShown&&matchMedia('(max-width:760px)').matches){installHintShown=true;setTimeout(showInstallHint,850)}}
function renderSpread(){if(!currentBook)return;const bookEl=$('#open-book');const last=currentBook.spreads.length;const cover=currentIndex<0,closing=currentIndex>=last;let left,right;if(cover){left=`<h1 class="spread-title">${esc(currentBook.title)}</h1><p class="spread-copy hand">${esc(currentBook.cover?.dedication||'A book of little moments')}</p><div class="spread-prompt">A story we made together</div>`;right=`<div class="spread-title">✳</div><p class="spread-copy hand">${esc(currentBook.location||'Open when you are ready.')}</p><div class="spread-prompt">Turn the page</div>`;$('#page-indicator').textContent='Cover'}else if(closing){left=`<h2 class="spread-title">Until next time</h2><p class="spread-copy hand">${esc(currentBook.spreads.at(-1)?.promptText||'Some stories keep going.')}</p>`;right='<div class="spread-title">✳</div><div class="spread-prompt">The end, for now</div>';$('#page-indicator').textContent='Closing page'}else{const s=currentBook.spreads[currentIndex],author=s.author||currentBook.author,ink=inkFor(author);left=`<h2 class="spread-title">${esc(s.title||'A little memory')}</h2><div class="spread-date">${esc(s.date||'')}</div><p class="spread-copy" style="color:${ink}">${esc(s.text||'')}</p>${renderItems(s.leftItems||[])}${s.promptText&&!s.text?`<div class="spread-prompt">${esc(s.promptText)}</div>`:''}<span class="page-number">${currentIndex*2+1}</span>${author?`<span class="author-corner" style="color:${ink}">${esc(author)}</span>`:''}`;right=`${renderItems(s.rightItems||[])}<button class="reader-note-trigger" aria-label="Leave a private note for the writer" title="Leave a private note">✎</button><span class="page-number">${currentIndex*2+2}</span>${author?`<span class="author-corner" style="color:${ink}">${esc(author)}</span>`:''}`;$('#page-indicator').textContent=`Spread ${currentIndex+1} of ${last}`;markRead(currentBook.id,s.id).then(()=>renderShelf())}bookEl.innerHTML=`<article class="page left">${left}</article><article class="page right">${right}</article><div class="flip-sheet" aria-hidden="true"></div>`;bookEl.classList.remove('turn-next','turn-prev');bookEl.querySelectorAll('[data-action]').forEach(el=>el.onclick=e=>{e.stopPropagation();itemAction(el.dataset.action,el)});const edges=bookEl.querySelectorAll('.page');edges[0].onclick=()=>turn(-1);edges[1].onclick=()=>turn(1);$('#prev-page').disabled=currentIndex<=-1;$('#next-page').disabled=currentIndex>=last;}
function renderItems(items){if(!items.length)return'';return `<div class="media-grid">${items.map(i=>{const rot=`--rotation:${i.rotation||0}deg`;if(i.type==='photo')return `<div class="memory-item photo-card" style="${rot}" data-action="flip"><div class="photo-art"></div><div class="photo-caption">${esc(i.caption||'A little scene')}</div><div class="photo-back">${esc(i.backNote||'A day worth keeping.')}</div></div>`;if(i.type==='gif')return `<div class="memory-item photo-card" style="${rot}"><div class="photo-art gif-art"></div><div class="photo-caption">${esc(i.caption||'Looping memory')}</div></div>`;if(i.type==='audio')return `<div class="memory-item audio-card" style="${rot}"><div class="cassette"></div><div>${esc(i.caption||'Listen again')}</div><button class="play-control" data-action="audio">▶ Play</button></div>`;if(i.type==='video')return `<div class="memory-item video-card" style="${rot}"><div class="video-window"></div><div>${esc(i.caption||'A few seconds')}</div><button class="play-control" data-action="video">▶ Play</button></div>`;return `<div class="memory-item note-card ${i.style==='ticket'?'ticket':''}" style="${rot}" data-action="unfold"><span class="folded-message">${esc(i.caption||'A note for you')}<br>tap to unfold</span><span class="hidden-message">${esc(i.message||'You make ordinary days feel like home.')}</span></div>`}).join('')}</div>`}
function itemAction(action,el){if(action==='flip')el.classList.toggle('flipped');if(action==='unfold')el.classList.toggle('unfolded');if(action==='audio'||action==='video'){if(activeAudio){activeAudio.stop?.();activeAudio=null;document.querySelectorAll('.playing').forEach(x=>x.classList.remove('playing'))}if(action==='audio'){const ctx=new AudioContext(),osc=ctx.createOscillator(),gain=ctx.createGain();osc.type='sine';osc.frequency.value=392;gain.gain.value=.035;osc.connect(gain).connect(ctx.destination);osc.start();activeAudio={stop:()=>{osc.stop();ctx.close()}};el.closest('.audio-card').classList.add('playing');el.textContent='■ Stop';el.onclick=e=>{e.stopPropagation();activeAudio?.stop();activeAudio=null;el.closest('.audio-card').classList.remove('playing');el.textContent='▶ Play'}}else{const win=el.closest('.video-card').querySelector('.video-window');if(!el._animation){el._animation=win.animate([{filter:'saturate(1)'},{filter:'sepia(.8)'},{filter:'saturate(1)'}],{duration:1600,iterations:Infinity});el.textContent='Ⅱ Pause'}else if(el._animation.playState==='running'){el._animation.pause();el.textContent='▶ Play'}else{el._animation.play();el.textContent='Ⅱ Pause'}el.onclick=e=>{e.stopPropagation();itemAction('video',el)}}}}
function turn(dir){if(!currentBook)return;const next=currentIndex+dir;if(next< -1||next>currentBook.spreads.length)return;const bookEl=$('#open-book');bookEl.classList.remove('turn-next','turn-prev');void bookEl.offsetWidth;bookEl.classList.add(dir>0?'turn-next':'turn-prev');setTimeout(()=>{currentIndex=next;renderSpread()},reduced?0:680)}
