let soundCtx=null;function toggleSound(){const b=$('#sound-toggle'),on=b.getAttribute('aria-pressed')!=='true';b.setAttribute('aria-pressed',on);if(on){soundCtx=new AudioContext();const buffer=soundCtx.createBuffer(1,soundCtx.sampleRate*2,soundCtx.sampleRate),data=buffer.getChannelData(0);for(let i=0;i<data.length;i++)data[i]=(Math.random()*2-1)*.025;const src=soundCtx.createBufferSource(),filter=soundCtx.createBiquadFilter(),gain=soundCtx.createGain();src.buffer=buffer;src.loop=true;filter.type='lowpass';filter.frequency.value=700;gain.gain.value=.16;src.connect(filter).connect(gain).connect(soundCtx.destination);src.start();soundCtx.src=src;b.innerHTML='Sound <span>Ⅱ</span>'}else{soundCtx?.close();soundCtx=null;b.innerHTML='Sound <span>♪</span>'}}
function showView(view){activeView=view;$('#view-popover').hidden=true;const panel=$('#view-panel');if(view==='shelf'){panel.hidden=true;renderShelf();return}panel.hidden=false;if(view==='timeline'){panel.innerHTML=`<button class="dialog-close" id="view-close">×</button><h2>Our timeline</h2><div class="timeline-list">${[...books].sort((a,b)=>(a.date||'').localeCompare(b.date||'')).map(b=>`<button class="timeline-book" data-book="${esc(b.id)}"><small>${esc(b.date||'')}</small><h3>${esc(b.title)}</h3><p>${b.spreads.length} little chapters</p></button>`).join('')}</div>`;panel.querySelectorAll('[data-book]').forEach(x=>x.onclick=()=>openBook(books.find(b=>b.id===x.dataset.book)))}else if(view==='constellation'){const nodes=books.map((b,i)=>({b,x:120+(i*137)%700,y:70+(i*83)%330}));const lines=nodes.flatMap((n,i)=>nodes.slice(i+1).filter(m=>n.b.people?.some(p=>m.b.people?.includes(p))||(n.b.location&&n.b.location===m.b.location)).map(m=>`<line class="star-link" x1="${n.x}" y1="${n.y}" x2="${m.x}" y2="${m.y}"/>`)).join('');panel.innerHTML=`<button class="dialog-close" id="view-close">×</button><h2>Our constellation</h2><svg class="star-map" viewBox="0 0 900 450" role="img" aria-label="Books as connected stars">${lines}${nodes.map(n=>`<g data-book="${esc(n.b.id)}" tabindex="0" role="button"><circle class="star-node" cx="${n.x}" cy="${n.y}" r="7"/><text x="${n.x+12}" y="${n.y+4}" fill="#eee0c3" font-size="13">${esc(n.b.title)}</text></g>`).join('')}</svg>`;panel.querySelectorAll('[data-book]').forEach(x=>x.onclick=()=>openBook(books.find(b=>b.id===x.dataset.book)))}else{panel.innerHTML=`<button class="dialog-close" id="view-close">×</button><h2>Places we kept</h2><p>Map tiles are requested only while this view is open. This sample has no saved coordinates.</p><div class="map-placeholder"><div class="map-note">No places pinned yet. The writer can add a place to a book.</div></div>`}$('#view-close').onclick=()=>showView('shelf')}

async function writerGate(){if(!selectedCharacter){$('#character-status').textContent='Choose froggiee or kyuu before opening the writer desk.';document.querySelector('.character-picker').scrollIntoView({behavior:'smooth',block:'center'});return}await unlockWriter(selectedCharacter)}
