function lockRoom(){writer=false;writerCharacter=null;selectedItem=null;document.querySelector('.writer-overlay')?.remove();if(!reader.hidden)closeBook();room.hidden=false;}
function writerPanel(){document.querySelector('.writer-overlay')?.remove();const overlay=document.createElement('section');overlay.className='writer-overlay';overlay.style.cssText='position:fixed;inset:0;z-index:20;background:#342720;overflow:auto';overlay.innerHTML=`<div class="writer-top"><span>✳ Writer’s desk <span id="save-state" class="saved-state">Saved on this device</span></span><div class="writer-toolbar"><button id="undo">↶ Undo</button><button id="redo">↷ Redo</button><button id="share">Share link</button><button id="export">Print / PDF</button><button id="writer-lock">Lock room</button></div></div><div class="writer-shell"><aside class="writer-side"><h3>The shelf</h3><div class="writer-toolbar"><button id="new-book">＋ New journal</button><button id="archive-toggle">Show archived</button></div><div id="manage-books"></div><hr><h3 id="manage-title">Choose a book</h3><div id="spread-tools"></div><div id="spread-list" class="spread-list"></div></aside><div class="writer-main" id="writer-main"><p class="canvas-hint">Choose a journal, then a spread to begin arranging its pages.</p></div></div>`;document.body.append(overlay);$('#writer-lock').onclick=lockRoom;$('#undo').onclick=undo;$('#redo').onclick=redo;$('#new-book').onclick=addBook;$('#archive-toggle').onclick=()=>{overlay.dataset.archived=overlay.dataset.archived==='true'?'false':'true';renderManageBooks()};$('#share').onclick=shareBooks;$('#export').onclick=writerExport;renderManageBooks();drawHistoryButtons()}
function renderManageBooks(){if(!writer)return;const include=$('.writer-overlay')?.dataset.archived==='true';$('#manage-books').innerHTML=books.filter(b=>include||!b.archived).map(b=>`<div class="manage-row"><button data-select-book="${esc(b.id)}">${esc(b.title)}</button><button data-lock-book="${esc(b.id)}" title="Set book lock">⌑</button><button data-archive-book="${esc(b.id)}" title="Archive">${b.archived?'↩':'⌄'}</button></div>`).join('');document.querySelectorAll('[data-select-book]').forEach(x=>x.onclick=()=>selectWriterBook(books.find(b=>b.id===x.dataset.selectBook)));document.querySelectorAll('[data-archive-book]').forEach(x=>x.onclick=()=>{const b=books.find(y=>y.id===x.dataset.archiveBook);pushHistory();b.archived=!b.archived;scheduleSave();renderManageBooks();renderShelf()});document.querySelectorAll('[data-lock-book]').forEach(x=>x.onclick=()=>bookLock(books.find(y=>y.id===x.dataset.lockBook)))}
let writerBook=null,writerSpread=null;
function selectWriterBook(book){writerBook=book;writerSpread=book.spreads[0]||null;$('#manage-title').textContent=book.title;$('#spread-tools').innerHTML=`<div class="writer-toolbar"><button id="add-spread">＋ Add</button><button id="duplicate-spread">Duplicate</button><button id="delete-spread">Delete</button><button id="edit-book">Rename / details</button><button id="file-media">Add media file</button></div><input type="file" id="media-file" accept=".jpg,.jpeg,.png,.webp,.gif,.mp4,.mp3,.m4a,image/jpeg,image/png,image/webp,image/gif,video/mp4,audio/mpeg,audio/mp3,audio/mp4,audio/x-m4a" multiple hidden><div class="media-add"><button data-add-item="photo">Photo</button><button data-add-item="gif">GIF</button><button data-add-item="audio">Audio</button><button data-add-item="video">Video</button><button data-add-item="note">Note</button></div><div class="writer-toolbar"><button id="export-book">Share this book</button><button id="edit-location">Set location</button></div>`;$('#add-spread').onclick=()=>{pushHistory();const s=blankSpread();writerBook.spreads.push(s);writerSpread=s;scheduleSave();renderSpreadList();renderCanvas()};$('#duplicate-spread').onclick=()=>{if(!writerSpread)return;pushHistory();const s=structuredClone(writerSpread);s.id=crypto.randomUUID();const i=writerBook.spreads.indexOf(writerSpread);writerBook.spreads.splice(i+1,0,s);writerSpread=s;scheduleSave();renderSpreadList();renderCanvas()};$('#delete-spread').onclick=()=>{if(!writerSpread||!confirm('Delete this spread? You can undo.'))return;pushHistory();writerBook.spreads=writerBook.spreads.filter(s=>s!==writerSpread);writerSpread=writerBook.spreads[0]||null;scheduleSave();renderSpreadList();renderCanvas()};$('#edit-book').onclick=editBook;$('#file-media').onclick=()=>$('#media-file').click();$('#media-file').onchange=e=>addFiles(e.target.files);$('#edit-location').onclick=editLocation;$('#export-book').onclick=()=>shareBooks(book);document.querySelectorAll('[data-add-item]').forEach(x=>x.onclick=()=>addItem(x.dataset.addItem));$('#undo').onclick=undo;$('#redo').onclick=redo;renderSpreadList();renderCanvas()}
function blankSpread(){return{id:crypto.randomUUID(),leftItems:[],rightItems:[],background:'paper',promptText:'What made you laugh that day?',title:'A new memory',date:new Date().toLocaleDateString(),text:'',note:null}}
function renderSpreadList(){const el=$('#spread-list');if(!el)return;el.innerHTML=(writerBook?.spreads||[]).map((s,i)=>`<button class="spread-thumb ${s===writerSpread?'active':''}" draggable="true" data-spread="${s.id}">${String(i+1).padStart(2,'0')} · ${esc(s.title||'Untitled spread')}</button>`).join('');el.querySelectorAll('[data-spread]').forEach(x=>{x.onclick=()=>{writerSpread=writerBook.spreads.find(s=>s.id===x.dataset.spread);renderSpreadList();renderCanvas()};x.ondragstart=()=>dragging={type:'spread',id:x.dataset.spread};x.ondragover=e=>e.preventDefault();x.ondrop=e=>{e.preventDefault();if(dragging?.type!=='spread')return;pushHistory();const from=writerBook.spreads.findIndex(s=>s.id===dragging.id),to=writerBook.spreads.findIndex(s=>s.id===x.dataset.spread),[s]=writerBook.spreads.splice(from,1);writerBook.spreads.splice(to,0,s);scheduleSave();renderSpreadList()}})}
