function renderCanvas(){const main=$('#writer-main');if(!main)return;if(!writerSpread){main.innerHTML='<p class="canvas-hint">Add a spread to begin.</p>';return}main.innerHTML=`<label>Spread title <input id="spread-title" value="${esc(writerSpread.title||'')}" style="max-width:240px"></label> <label>Date <input id="spread-date" value="${esc(writerSpread.date||'')}" style="max-width:160px"></label><div class="canvas-spread">${['leftItems','rightItems'].map((side,si)=>`<div class="canvas-page" data-side="${side}"><div class="canvas-hint">${si?'Right':'Left'} page</div>${(writerSpread[side]||[]).map(i=>`<div class="canvas-item ${i.style==='clip'?'clip':'tape'} ${selectedItem===i?'selected':''}" data-item="${i.id}" style="left:${i.x}%;top:${i.y}%;width:${i.width}%;height:${Math.max(12,i.height)}px;transform:rotate(${i.rotation||0}deg) rotateX(${i.tilt||0}deg);font-size:14px">${esc(i.caption||placeholders[i.type])}</div>`).join('')}${writerSpread.promptText&&!allItems().length?`<div class="canvas-hint">${esc(writerSpread.promptText)}</div>`:''}</div>`).join('')}</div><div class="editor-inspector"><label>Prompt <input id="spread-prompt" value="${esc(writerSpread.promptText||'')}" style="width:180px"></label><label>Note <input id="spread-note" value="${esc(writerSpread.note||'')}" style="width:170px"></label><button id="spread-copy">Edit story text</button><span id="item-inspector"></span></div>`;$('#spread-title').onchange=e=>updateSpread('title',e.target.value);$('#spread-date').onchange=e=>updateSpread('date',e.target.value);$('#spread-prompt').onchange=e=>updateSpread('promptText',e.target.value);$('#spread-note').onchange=e=>updateSpread('note',e.target.value);$('#spread-copy').onclick=()=>editStory();document.querySelectorAll('.canvas-item').forEach(el=>{el.onpointerdown=startMove;el.onclick=()=>{selectedItem=allItems().find(i=>i.id===el.dataset.item);renderInspector()}});renderInspector()}
function updateSpread(k,v){pushHistory();writerSpread[k]=v;scheduleSave()}
function addItem(type,side='leftItems',caption=placeholders[type]){if(!writerSpread)return;pushHistory();const i={id:crypto.randomUUID(),type,caption,x:16+Math.random()*22,y:20+Math.random()*26,width:type==='note'?30:38,height:90,rotation:(Math.random()*6-3),tilt:0,style:'tape',mediaId:null};writerSpread[side].push(i);selectedItem=i;scheduleSave();renderCanvas()}
function startMove(e){e.preventDefault();const el=e.currentTarget;selectedItem=allItems().find(i=>i.id===el.dataset.item);pushHistory();const page=el.parentElement,rect=page.getBoundingClientRect(),startX=e.clientX,startY=e.clientY,ox=selectedItem.x,oy=selectedItem.y;el.setPointerCapture(e.pointerId);el.onpointermove=ev=>{selectedItem.x=Math.max(0,Math.min(80,ox+(ev.clientX-startX)/rect.width*100));selectedItem.y=Math.max(0,Math.min(80,oy+(ev.clientY-startY)/rect.height*100));el.style.left=selectedItem.x+'%';el.style.top=selectedItem.y+'%'};el.onpointerup=()=>{el.onpointermove=null;scheduleSave();renderInspector()}}
function renderInspector(){const host=$('#item-inspector');if(!host)return;if(!selectedItem){host.innerHTML='';return}host.innerHTML=`<label>Size <input type="range" min="15" max="65" value="${selectedItem.width}" id="item-size"></label><label>Rotate <input type="range" min="-20" max="20" value="${selectedItem.rotation||0}" id="item-rotation"></label><label>Tilt <input type="range" min="-12" max="12" value="${selectedItem.tilt||0}" id="item-tilt"></label><label>Tape <input id="item-tape" type="checkbox" ${selectedItem.style==='tape'?'checked':''}></label><button id="item-caption">Caption</button><button id="item-delete">Remove</button>`;$('#item-size').oninput=e=>{selectedItem.width=+e.target.value;document.querySelector(`[data-item="${selectedItem.id}"]`).style.width=`${selectedItem.width}%`};$('#item-size').onchange=()=>scheduleSave();$('#item-rotation').oninput=e=>{selectedItem.rotation=+e.target.value;document.querySelector(`[data-item="${selectedItem.id}"]`).style.transform=`rotate(${selectedItem.rotation}deg) rotateX(${selectedItem.tilt||0}deg)`};$('#item-rotation').onchange=()=>scheduleSave();$('#item-tilt').oninput=e=>{selectedItem.tilt=+e.target.value;document.querySelector(`[data-item="${selectedItem.id}"]`).style.transform=`rotate(${selectedItem.rotation||0}deg) rotateX(${selectedItem.tilt}deg)`};$('#item-tilt').onchange=()=>scheduleSave();$('#item-tape').onchange=e=>{selectedItem.style=e.target.checked?'tape':'clip';scheduleSave()};$('#item-caption').onclick=()=>{const text=prompt('Caption for this keepsake',selectedItem.caption||'');if(text!==null){pushHistory();selectedItem.caption=text;scheduleSave();renderCanvas()}};$('#item-delete').onclick=()=>{pushHistory();writerSpread.leftItems=writerSpread.leftItems.filter(i=>i!==selectedItem);writerSpread.rightItems=writerSpread.rightItems.filter(i=>i!==selectedItem);selectedItem=null;scheduleSave();renderCanvas()}}
function editStory(){showDialog(`<h2>Words for this spread</h2><label>Story</label><textarea id="story-text" rows="6">${esc(writerSpread.text||'')}</textarea><div class="dialog-actions"><button id="story-save">Keep these words</button></div>`);$('#story-save').onclick=()=>{pushHistory();writerSpread.text=$('#story-text').value;dialog.close();scheduleSave()}}
function editBook(){showDialog(`<h2>Book details</h2><label>Spine title</label><input id="book-name" value="${esc(writerBook.title)}"><label>Cover color</label><input id="book-color" type="color" value="${esc(writerBook.color||'#60766a')}"><label>Cover style</label><select id="book-style"><option value="leather">Soft leather</option><option value="cloth">Book cloth</option><option value="paper">Wrapped paper</option></select><label>Dedication</label><input id="book-dedication" value="${esc(writerBook.cover?.dedication||'')}"><div class="dialog-actions"><button id="book-save">Save details</button></div>`);$('#book-style').value=writerBook.coverStyle||'leather';$('#book-save').onclick=()=>{pushHistory();writerBook.title=$('#book-name').value;writerBook.color=$('#book-color').value;writerBook.coverStyle=$('#book-style').value;writerBook.cover.dedication=$('#book-dedication').value;$('#manage-title').textContent=writerBook.title;dialog.close();scheduleSave();renderManageBooks();renderShelf()}}
function editLocation(){showDialog(`<h2>Pin a place</h2><p>Location is optional. It stays on this device unless you sync the book.</p><label>Place name</label><input id="place-name" value="${esc(writerBook.location||'')}"><label>Latitude (optional)</label><input id="place-lat" type="number" step="any" value="${writerBook.coordinates?.lat||''}"><label>Longitude (optional)</label><input id="place-lng" type="number" step="any" value="${writerBook.coordinates?.lng||''}"><div class="dialog-actions"><button id="place-save">Save place</button></div>`);$('#place-save').onclick=()=>{pushHistory();writerBook.location=$('#place-name').value;const lat=parseFloat($('#place-lat').value),lng=parseFloat($('#place-lng').value);writerBook.coordinates=Number.isFinite(lat)&&Number.isFinite(lng)?{lat,lng}:null;dialog.close();scheduleSave()}}
function bookLock(book){showDialog(`<h2>Journal lock</h2><p>Add a date or a password key. Leave both empty to open the book to every reader.</p><label>Prompt</label><input id="lock-prompt" value="${esc(book.lock?.prompt||'What date should open this book?')}"><label>Date or password</label><input id="lock-value" value="${esc(book.lock?.value||'')}"><div class="dialog-actions"><button id="lock-save">Save lock</button><button id="lock-clear" class="secondary">Remove lock</button></div>`);$('#lock-save').onclick=()=>{pushHistory();book.lock={prompt:$('#lock-prompt').value,value:$('#lock-value').value};dialog.close();scheduleSave();renderManageBooks();renderShelf()};$('#lock-clear').onclick=()=>{pushHistory();book.lock=null;dialog.close();scheduleSave();renderManageBooks();renderShelf()}}
function addBook(){const title=prompt('What should this journal be called?','A new little story');if(!title)return;pushHistory();const b={id:crypto.randomUUID(),title,date:new Date().toISOString().slice(0,10),location:'',coordinates:null,coverStyle:'walnut',color:'#8d5740',lock:null,archived:false,version:1,people:[],cover:{title,dedication:'A book of little moments'},spreads:[blankSpread()]};books.push(b);scheduleSave();renderShelf();if(writer){renderManageBooks();selectWriterBook(b)}}
function addFiles(files){for(const file of files){const type=file.type.startsWith('image/')?(file.type==='image/gif'?'gif':'photo'):file.type.startsWith('video/')?'video':'audio';addItem(type,'leftItems',file.name);const item=selectedItem;item.fileType=file.type;const reader=new FileReader();reader.onload=()=>{item.preview=reader.result;scheduleSave()};reader.readAsDataURL(file)}}
function pushHistory(){if(!writer)return;history.push(JSON.stringify({books,writerBookId:writerBook?.id,spreadId:writerSpread?.id}));if(history.length>100)history.shift();future=[];drawHistoryButtons()}
function undo(){if(!history.length)return;future.push(JSON.stringify({books,writerBookId:writerBook?.id,spreadId:writerSpread?.id}));const snap=JSON.parse(history.pop());books=snap.books;writerBook=books.find(b=>b.id===snap.writerBookId)||null;writerSpread=writerBook?.spreads.find(s=>s.id===snap.spreadId)||writerBook?.spreads[0]||null;scheduleSave();renderManageBooks();if(writerBook){$('#manage-title').textContent=writerBook.title;renderSpreadList();renderCanvas()}drawHistoryButtons()}
function redo(){if(!future.length)return;history.push(JSON.stringify({books,writerBookId:writerBook?.id,spreadId:writerSpread?.id}));const snap=JSON.parse(future.pop());books=snap.books;writerBook=books.find(b=>b.id===snap.writerBookId)||null;writerSpread=writerBook?.spreads.find(s=>s.id===snap.spreadId)||writerBook?.spreads[0]||null;scheduleSave();renderManageBooks();if(writerBook){renderSpreadList();renderCanvas()}drawHistoryButtons()}
function drawHistoryButtons(){const u=$('#undo'),r=$('#redo');if(u)u.disabled=!history.length;if(r)r.disabled=!future.length}
function scheduleSave(){if(!writer)return;$('#save-state').textContent=navigator.onLine?'Saving…':'Offline · will sync';clearTimeout(saveTimer);saveTimer=setTimeout(saveNow,800)}
async function saveNow(){await setBooks(books);if(!sync.enabled()){if($('#save-state'))$('#save-state').textContent='Saved on this device';return}try{for(const b of books){const previous=b.version||0;b.version=previous+1;try{await sync.save({id:b.id,version:b.version,position:books.indexOf(b),doc:b})}catch(error){if(error.message!=='VERSION_CONFLICT'){b.version=previous;throw error}const row=await sync.load(b.id);if(!row?.doc)throw error;const remote=row.doc,remoteSpreads=remote.spreads||[],byId=new Map(remoteSpreads.map(s=>[s.id,s]));for(const s of b.spreads||[])byId.set(s.id,s);Object.assign(b,{...remote,...b,spreads:[...remoteSpreads.map(s=>byId.get(s.id)),...(b.spreads||[]).filter(s=>!remoteSpreads.some(r=>r.id===s.id))],version:row.version+1});await sync.save({id:b.id,version:b.version,position:books.indexOf(b),doc:b})}}if($('#save-state'))$('#save-state').textContent='Saved and synced'}catch(e){if($('#save-state'))$('#save-state').textContent=e.message==='VERSION_CONFLICT'?'Sync conflict · saved here; retry after reload':'Saved here · sync paused'}await setBooks(books)}
window.addEventListener('online',()=>{if(writer)scheduleSave()});
async function shareBooks(book=null){if(!(book||writerBook||books[0]))return;showDialog(`<h2>Share this shelf</h2><p>This link opens the collection. Without encryption, book text and uploaded media are stored as readable data in your configured Supabase project.</p><div class="dialog-actions"><button id="make-link">Create link</button></div><input id="share-url" readonly aria-label="Share URL" style="margin-top:12px" placeholder="Your link will appear here">`);$('#make-link').onclick=async()=>{if(sync.enabled())await saveNow();const link=`${location.origin}${location.pathname}?collection=1`;$('#share-url').value=link;await navigator.clipboard?.writeText(link).catch(()=>{});$('#share-url').select()}}
async function openShare(){try{if(sync.enabled()){const rows=await sync.list();if(rows.length)books=rows.map(r=>({...r.doc,version:r.version}))}}catch(e){console.warn('Could not load the shared collection',e)}renderShelf()}
async function writerExport(){if(!confirm('Prepare a print-ready version of the whole collection?'))return;try{exportCollection(books)}catch(e){alert(e.message)}}
async function leaveReaderMark(){const spread=currentBook?.spreads[currentIndex];if(!spread)return;showDialog(`<h2>Leave a little note</h2><p>Only the writer can see this margin note.</p><label for="reader-mark-text">Your note</label><textarea id="reader-mark-text" rows="4" maxlength="500" placeholder="A thought from this page…"></textarea><div class="dialog-actions"><button id="reader-mark-save">Save note</button><button id="reader-mark-cancel" class="secondary">Cancel</button></div>`);$('#reader-mark-cancel').onclick=()=>dialog.close();$('#reader-mark-save').onclick=async()=>{const value=$('#reader-mark-text').value.trim();if(!value){dialog.close();return}const book=currentBook,old=book.version||0;spread.readerMark=value;spread.readerMarkBy=selectedCharacter;book.version=old+1;try{if(sync.enabled())await sync.save({id:book.id,version:book.version,position:books.indexOf(book),doc:book});dialog.close()}catch(error){if(error.message!=='VERSION_CONFLICT'){book.version=old;spread.readerMark=null;alert('The note could not be saved. Try again when online.');return}const row=await sync.load(book.id),remote=row.doc,target=remote.spreads.find(s=>s.id===spread.id);if(!target){book.version=old;return}target.readerMark=value;book.spreads=remote.spreads;book.version=row.version+1;await sync.save({id:book.id,version:book.version,position:books.indexOf(book),doc:book});dialog.close()}}}
let deferredInstall=null;window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();deferredInstall=e});
function showInstallHint(){showDialog(`<h2>Keep this shelf close</h2><p>${deferredInstall?'Add the shelf to your home screen for a quiet shortcut.':'Use your browser’s “Add to Home Screen” option to return to this shelf like an app.'}</p>${deferredInstall?'<div class="dialog-actions"><button id="install-now">Add to Home Screen</button></div>':''}`);if(deferredInstall)$('#install-now').onclick=async()=>{await deferredInstall.prompt();await deferredInstall.userChoice;deferredInstall=null;dialog.close()}}
const toolsObserver=new MutationObserver(()=>{const tools=$('#spread-tools');if(writer&&tools&&!tools.querySelector('#record-voice')){const button=document.createElement('button');button.id='record-voice';button.textContent='Record voice note';button.onclick=recordVoice;tools.querySelector('.writer-toolbar')?.append(button)}});toolsObserver.observe(document.body,{childList:true,subtree:true});
const photoToolsObserver=new MutationObserver(()=>{const tools=$('#spread-tools');if(!writer||!tools||tools.querySelector('#sort-photo-batch'))return;const button=document.createElement('button');button.id='sort-photo-batch';button.textContent='Sort photo batch';const input=document.createElement('input');input.type='file';input.multiple=true;input.accept='.jpg,.jpeg,.png,.webp,image/jpeg,image/png,image/webp';input.hidden=true;input.id='photo-sort-file';tools.append(button,input);button.onclick=()=>input.click();input.onchange=()=>preparePhotoGroups(input.files)});photoToolsObserver.observe(document.body,{childList:true,subtree:true});
async function preparePhotoGroups(files){const records=await Promise.all([...files].map(readPhotoMetadata));if(!records.length)return;showDialog(`<h2>Sort these photos</h2><p>Dates come from the photos when available, and otherwise from the file date. GPS stays in memory until you choose to keep it.</p><label><input id="keep-gps" type="checkbox"> Keep and group by uploaded GPS coordinates</label><div id="photo-groups"></div><div class="dialog-actions"><button id="make-photo-spreads">Suggest spreads</button><button id="cancel-photo-sort" class="secondary">Cancel</button></div>`);const renderGroups=()=>{const keep=$('#keep-gps').checked,map=new Map();for(const r of records){const point=keep&&r.coordinates?`${r.coordinates.lat.toFixed(2)}, ${r.coordinates.lng.toFixed(2)}`:'';const key=`${r.date}|${point}`;if(!map.has(key))map.set(key,{date:r.date,point,coordinates:point?r.coordinates:null,records:[]});map.get(key).records.push(r)}$('#photo-groups').innerHTML=[...map.values()].map(g=>`<p>${esc(g.date)}${g.point?` · ${esc(g.point)}`:''} — ${g.records.length} photo${g.records.length===1?'':'s'}</p>`).join('');return [...map.values()]};$('#keep-gps').onchange=renderGroups;$('#cancel-photo-sort').onclick=()=>dialog.close();$('#make-photo-spreads').onclick=async()=>{const groups=renderGroups();pushHistory();for(const group of groups){const spread=blankSpread();spread.title=group.date;spread.date=group.date;spread.promptText='What do you remember about this day?';if(group.point){spread.location=group.point;spread.coordinates=group.coordinates;if(!writerBook.coordinates)writerBook.coordinates=group.coordinates}writerBook.spreads.push(spread);writerSpread=spread;for(let i=0;i<group.records.length;i++)await addFiles([group.records[i].file],i%2?'rightItems':'leftItems')}dialog.close();renderSpreadList();renderCanvas();scheduleSave()}}
async function recordVoice(){if(!navigator.mediaDevices?.getUserMedia||!window.MediaRecorder){alert('Voice recording is not supported in this browser.');return}try{const stream=await navigator.mediaDevices.getUserMedia({audio:true}),mime=MediaRecorder.isTypeSupported('audio/mp4')?'audio/mp4':'audio/webm',recorder=new MediaRecorder(stream,{mimeType:mime}),parts=[];let keep=false;recorder.ondataavailable=e=>{if(e.data.size)parts.push(e.data)};recorder.onstop=async()=>{stream.getTracks().forEach(t=>t.stop());dialog.close();if(keep){const blob=new Blob(parts,{type:mime}),file=new File([blob],`voice-note.${mime==='audio/mp4'?'m4a':'webm'}`,{type:mime});await addFiles([file])}};showDialog(`<h2>Recording a little note</h2><p class="record-indicator">● Recording… Speak whenever you’re ready.</p><div class="dialog-actions"><button id="record-save">Stop and keep</button><button class="secondary" id="record-discard">Discard</button></div>`);$('#record-save').onclick=()=>{keep=true;recorder.stop()};$('#record-discard').onclick=()=>{keep=false;recorder.stop()};recorder.start()}catch(e){alert(`Microphone access was not granted: ${e.message}`)}}
// One-time migration for files created by the earlier encrypted prototype.
async function migrateLegacyData(password){let changed=false;if(sync.enabled()){try{const rows=await sync.list(),loaded=[];for(const row of rows){let doc=row.doc;if(doc?.sealed&&doc.keyEnvelope){const key=await unwrapLegacyBookKey(doc.keyEnvelope,password);legacyKeys.set(row.id,key);doc=await openLegacyJSON(doc.sealed,key);doc.keyEnvelope=row.doc.keyEnvelope;changed=true}doc.version=row.version;loaded.push(doc)}if(loaded.length)books=loaded}catch(e){console.warn('Could not load the remote shelf yet',e)}}for(const book of books){if(book.keyEnvelope&&!legacyKeys.has(book.id)){try{legacyKeys.set(book.id,await unwrapLegacyBookKey(book.keyEnvelope,password))}catch(e){console.warn('Legacy media needs the original writer password',e)}}const key=legacyKeys.get(book.id);for(const spread of book.spreads||[])for(const item of [...(spread.leftItems||[]),...(spread.rightItems||[])]){if(!item.mediaId)continue;let entry=await getValue(`media:${item.mediaId}`),blob=entry?.blob,remote=false;if(!blob&&sync.enabled()){try{blob=await sync.getMedia(item.mediaId);remote=!!blob}catch{}}const mime=item.fileType||entry?.mime||blob?.type||'application/octet-stream';if(blob&&key&&(entry?.legacyEncrypted||blob.type==='application/octet-stream')){try{blob=await decryptLegacyBlob(blob,key,mime);entry={blob,bookId:book.id,mime,plain:true};await setValue(`media:${item.mediaId}`,entry);if(sync.enabled()){if(navigator.onLine)await sync.uploadMedia(item.mediaId,blob);else{const queue=await getValue('media-queue-index')||[];await setValue('media-queue-index',[...new Set([...queue,item.mediaId])])}}changed=true}catch(e){console.warn('A legacy media item could not be migrated',e)}}else if(blob&&!entry){entry={blob,bookId:book.id,mime,plain:true};await setValue(`media:${item.mediaId}`,entry)}item.fileType=item.fileType||mime}if(book.keyEnvelope){delete book.keyEnvelope;changed=true}}legacyKeys.clear();return changed}
// Media rendering is direct: newly added files stay as regular Blobs.
renderItems = function(items){if(!items.length)return'';return `<div class="media-grid">${items.map(i=>{const rot=`--rotation:${i.rotation||0}deg;--tilt:${i.tilt||0}deg`,mid=i.mediaId?`data-media-id="${esc(i.mediaId)}" data-media-type="${esc(i.fileType||'')}"`:'';if(i.type==='photo')return `<div class="memory-item photo-card" style="${rot}" data-action="flip"><div class="photo-art media-art" ${mid}></div><div class="photo-caption">${esc(i.caption||'A little scene')}</div><div class="photo-back">${esc(i.backNote||'A day worth keeping.')}</div></div>`;if(i.type==='gif')return `<div class="memory-item photo-card" style="${rot}">${i.mediaId?`<img class="photo-art gif-art media-image" ${mid} alt="${esc(i.caption||'Animated memory')}">`:'<div class="photo-art gif-art"></div>'}<div class="photo-caption">${esc(i.caption||'Looping memory')}</div></div>`;if(i.type==='audio')return i.mediaId?`<div class="memory-item audio-card" style="${rot}"><div class="cassette"></div><div>${esc(i.caption||'Listen again')}</div><audio class="media-audio" ${mid} controls aria-label="${esc(i.caption||'Audio memory')}"></audio></div>`:`<div class="memory-item audio-card" style="${rot}"><div class="cassette"></div><div>${esc(i.caption||'Listen again')}</div><button class="play-control" data-action="audio">▶ Play</button></div>`;if(i.type==='video')return i.mediaId?`<div class="memory-item video-card" style="${rot}"><video class="video-window media-video" ${mid} controls loop playsinline aria-label="${esc(i.caption||'Video memory')}"></video><div>${esc(i.caption||'A few seconds')}</div></div>`:`<div class="memory-item video-card" style="${rot}"><div class="video-window"></div><div>${esc(i.caption||'A few seconds')}</div><button class="play-control" data-action="video">▶ Play</button></div>`;return `<div class="memory-item note-card ${i.style==='ticket'?'ticket':''}" style="${rot}" data-action="unfold"><span class="folded-message">${esc(i.caption||'A note for you')}<br>tap to unfold</span><span class="hidden-message">${esc(i.message||'You make ordinary days feel like home.')}</span></div>`}).join('')}</div>`};
renderSpread = function(){if(!currentBook)return;const bookEl=$('#open-book'),last=currentBook.spreads.length,cover=currentIndex<0,closing=currentIndex>=last;bookEl.classList.toggle('cover-open',cover);bookEl.dataset.coverStyle=currentBook.coverStyle||'leather';bookEl.style.setProperty('--book-cover',currentBook.color||'#60766a');let left,right;if(cover){left=`<h1 class="spread-title">${esc(currentBook.title)}</h1><p class="spread-copy hand">${esc(currentBook.cover?.dedication||'A book of little moments')}</p><div class="spread-prompt">A story we made together</div>`;right=`<div class="spread-title">✳</div><p class="spread-copy hand">${esc(currentBook.location||'Open when you are ready.')}</p><div class="spread-prompt">Turn the page</div>`;$('#page-indicator').textContent='Cover'}else if(closing){left=`<h2 class="spread-title">Until next time</h2><p class="spread-copy hand">${esc(currentBook.spreads.at(-1)?.promptText||'Some stories keep going.')}</p>`;right='<div class="spread-title">✳</div><div class="spread-prompt">The end, for now</div>';$('#page-indicator').textContent='Closing page'}else{const s=currentBook.spreads[currentIndex];left=`<h2 class="spread-title">${esc(s.title||'A little memory')}</h2><div class="spread-date">${esc(s.date||'')}</div><p class="spread-copy">${esc(s.text||'')}</p>${renderItems(s.leftItems||[])}${s.promptText&&!s.text?`<div class="spread-prompt">${esc(s.promptText)}</div>`:''}<span class="page-number">${currentIndex*2+1}</span>`;right=`${renderItems(s.rightItems||[])}<button class="reader-note-trigger" aria-label="Leave a private note for the writer" title="Leave a private note">✎</button><span class="page-number">${currentIndex*2+2}</span>`;$('#page-indicator').textContent=`Spread ${currentIndex+1} of ${last}`;markRead(currentBook.id,s.id).then(()=>renderShelf())}bookEl.innerHTML=`<article class="page left">${left}</article><article class="page right">${right}</article><div class="flip-sheet" aria-hidden="true"></div>`;bookEl.classList.remove('turn-next','turn-prev');bookEl.querySelectorAll('[data-action]').forEach(el=>el.onclick=e=>{e.stopPropagation();itemAction(el.dataset.action,el)});bookEl.querySelector('.reader-note-trigger')?.addEventListener('click',e=>{e.stopPropagation();leaveReaderMark()});const pages=bookEl.querySelectorAll('.page');pages[0].onclick=()=>turn(-1);pages[1].onclick=()=>turn(1);$('#prev-page').disabled=currentIndex<=-1;$('#next-page').disabled=currentIndex>=last;hydrateMedia(bookEl)};
async function hydrateMedia(container){for(const el of container.querySelectorAll('[data-media-id]')){const id=el.dataset.mediaId;if(mediaURLs.has(id)){applyMedia(el,mediaURLs.get(id));continue}try{let entry=await getValue(`media:${id}`),blob=entry?.blob;if(!blob&&sync.enabled())blob=await sync.getMedia(id);if(!blob)continue;const oldCipher=blob.type==='application/octet-stream'&&!entry?.plain,key=legacyKeys.get(entry?.bookId||currentBook?.id);if(oldCipher&&key){blob=await decryptLegacyBlob(blob,key,entry?.mime||el.dataset.mediaType);entry={...entry,blob,plain:true};await setValue(`media:${id}`,entry)}else if(oldCipher&&!key){const hint=document.createElement('small');hint.className='media-migration-hint';hint.textContent='Unlock Writer once to prepare this older recording for playback.';el.after(hint);continue}const mime=entry?.mime||el.dataset.mediaType||blob.type||'application/octet-stream',url=URL.createObjectURL(blob.type===mime?blob:new Blob([blob],{type:mime}));mediaURLs.set(id,url);applyMedia(el,url)}catch(e){console.warn('Media could not be loaded',e)}}}
function applyMedia(el,url){if(el.tagName==='IMG')el.src=url;else if(el.tagName==='AUDIO'||el.tagName==='VIDEO')el.src=url;else el.style.backgroundImage=`url("${url}")`}
