 main.querySelectorAll('.text-content[contenteditable="true"]').forEach(el=>{const item=allItems().find(x=>x.id===el.dataset.textId);el.onfocus=()=>{selectedItem=item;el.dataset.undoCaptured='false';renderInspector()};el.oninput=()=>{if(!item)return;if(el.dataset.undoCaptured!=='true'){pushHistory();el.dataset.undoCaptured='true'}item.caption=el.innerText;scheduleSave()}});
  const story=main.querySelector('.writer-story');if(story?.isContentEditable){story.onfocus=()=>{story.dataset.undoCaptured='false'};story.oninput=()=>{if(story.dataset.undoCaptured!=='true'){pushHistory();story.dataset.undoCaptured='true'}writerSpread.text=story.innerText;writerSpread.textAuthor=writerCharacter;writerSpread.textInkColor=inkFor(writerCharacter);const page=story.closest('.page');page.querySelectorAll('.author-corner,.author-corner-group').forEach(badge=>badge.remove());page.insertAdjacentHTML('beforeend',authorBadges(pageAuthors(writerSpread,'leftItems')));scheduleSave()}}
 main.querySelectorAll('.canvas-page').forEach(page=>page.onclick=e=>{if(e.target.closest('.memory-item,.author-corner,.spread-title,.spread-date,.spread-copy,.page-number,.spread-prompt,[contenteditable="true"]'))return;const rect=page.getBoundingClientRect(),itemSide=page.dataset.side;addItem('text',itemSide,'');selectedItem.x=Math.max(2,Math.min(78,(e.clientX-rect.left)/rect.width*100));selectedItem.y=Math.max(5,Math.min(86,(e.clientY-rect.top)/rect.height*100));selectedItem.caption='';scheduleSave();renderCanvas();document.querySelector(`[data-text-id="${selectedItem.id}"]`)?.focus()});
