async function attachFileToItem(item,file){if(!item)return;if(!file.type.match(/^(image\/(jpeg|png|webp|gif)|video\/mp4|audio\/(mpeg|mp3|mp4|x-m4a|webm))$/)){alert(`Unsupported file: ${file.name}`);return}if(file.size>60*1024*1024){alert(`${file.name} is over 60 MB.`);return}item.type=file.type==='image/gif'?'gif':file.type.startsWith('image/')?'photo':file.type.startsWith('video/')?'video':'audio';item.caption=file.name;item.author=writerCharacter;item.inkColor=inkFor(writerCharacter);item.accentColor=accentFor(writerCharacter);item.captionAuthor=writerCharacter;item.captionInkColor=inkFor(writerCharacter);item.fileType=file.type;const id=item.mediaId||crypto.randomUUID();const oldURL=mediaURLs.get(id);if(oldURL)URL.revokeObjectURL(oldURL);mediaURLs.delete(id);item.mediaId=id;await setValue(`media:${id}`,{blob:file,bookId:writerBook.id,mime:file.type,plain:true});if(sync.enabled()){const queue=await getValue('media-queue-index')||[];await setValue('media-queue-index',[...new Set([...queue,id])]);if(navigator.onLine){try{await sync.uploadMedia(id,file);await setValue('media-queue-index',(await getValue('media-queue-index')||[]).filter(value=>value!==id))}catch{}}}scheduleSave();renderCanvas()}
const oldRenderInspector=renderInspector;renderInspector=function(){oldRenderInspector();const host=$('#item-inspector');if(!host||!selectedItem)return;for(const selector of ['#item-size','#item-rotation','#item-tilt']){const input=host.querySelector(selector);if(!input)continue;const prior=input.oninput;let captured=false;input.oninput=e=>{if(!captured){pushHistory();captured=true}prior?.(e)};const finish=input.onchange;input.onchange=e=>{finish?.(e);captured=false}}const tape=host.querySelector('#item-tape');if(tape){const prior=tape.onchange;tape.onchange=e=>{pushHistory();prior?.(e)}}if(selectedItem.type==='text'){if((selectedItem.author||'froggiee')!==writerCharacter)host.insertAdjacentHTML('afterbegin',`<p class="item-authorship-hint">Written by ${esc(selectedItem.author||'froggiee')}. Add another note to write in your own color; this one keeps its original ink.</p>`);host.insertAdjacentHTML('afterbegin',`<label>Align <select id="text-align"><option value="left">Left</option><option value="center">Center</option><option value="right">Right</option></select></label><label>Ink size <input id="text-size" type="range" min="14" max="42" value="${selectedItem.fontSize||22}"></label>`);$('#text-align').value=selectedItem.align||'left';$('#text-align').onchange=e=>{pushHistory();selectedItem.align=e.target.value;renderCanvas();scheduleSave()};let captured=false;$('#text-size').oninput=e=>{if(!captured){pushHistory();captured=true}selectedItem.fontSize=+e.target.value;const node=document.querySelector(`[data-item="${selectedItem.id}"]`);if(node)node.style.fontSize=`${selectedItem.fontSize}px`};$('#text-size').onchange=()=>{captured=false;scheduleSave()}}if(['photo','gif','audio','video'].includes(selectedItem.type)){const button=document.createElement('button');button.type='button';button.textContent='Attach / replace file';button.onclick=()=>$('#writer-attach-file')?.click();host.append(button)}const caption=host.querySelector('#item-caption');if(caption){if(selectedItem.type==='text'&&(selectedItem.author||'froggiee')!==writerCharacter)caption.disabled=true;caption.onclick=()=>{const value=prompt('Caption for this keepsake',selectedItem.caption||'');if(value!==null){pushHistory();selectedItem.caption=value;selectedItem.captionAuthor=writerCharacter;selectedItem.captionInkColor=inkFor(writerCharacter);scheduleSave();renderCanvas()}}}};
startMove = function(e){e.preventDefault();const el=e.currentTarget;selectedItem=allItems().find(i=>i.id===el.dataset.item);if(!selectedItem)return;pushHistory();const page=el.closest('.canvas-page,.page'),rect=page.getBoundingClientRect(),startX=e.clientX,startY=e.clientY,ox=selectedItem.x||0,oy=selectedItem.y||0;el.setPointerCapture(e.pointerId);el.onpointermove=ev=>{selectedItem.x=Math.max(0,Math.min(88,ox+(ev.clientX-startX)/rect.width*100));selectedItem.y=Math.max(0,Math.min(88,oy+(ev.clientY-startY)/rect.height*100));el.style.left=selectedItem.x+'%';el.style.top=selectedItem.y+'%'};el.onpointerup=ev=>{el.onpointermove=null;const target=document.elementFromPoint(ev.clientX,ev.clientY)?.closest('.canvas-page,.page');if(target&&target!==page){const from=page.dataset.side,to=target.dataset.side;if(from&&to){writerSpread[from]=writerSpread[from].filter(i=>i!==selectedItem);writerSpread[to].push(selectedItem);selectedItem.x=12;selectedItem.y=22}}scheduleSave();renderCanvas()}};
const originalAddItem=addItem;addItem=function(type,side='leftItems',caption=placeholders[type]){if(!writerSpread)return;originalAddItem(type,side,caption);if(selectedItem){selectedItem.x=type==='text'?18:12;selectedItem.y=type==='text'?28:24;selectedItem.width=type==='text'?45:38;selectedItem.height=type==='text'?65:120;if(type==='text'){selectedItem.align='left';selectedItem.fontSize=22;selectedItem.caption=caption||''}scheduleSave();renderCanvas()}};

